/*
 * A044239  Numbers k such that string 6,4 occurs in the base 8 representation
 *          of k but not of k-1.
 * https://oeis.org/A044239
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) = k such that the base‑8 representation of k contains * the
 *            substring 64 but the base‑8 representation of k‑1 does not. *
 *            The sequence is generated by scanning integers from 1 upward and
 *            * keeping the first n such k
 * Range:     u8 n <= 4, u16 n <= 1136, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   has_64
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stdlib.h>
#include "../utils/has_64.h"

seq_t a(idx_t n) {
    static seq_t *cache = NULL;
    static size_t cache_len = 0;
    static size_t cache_cap = 0;
    static seq_t next_scan = 1;      /* next integer to test */

    if (n == 0)
        return 0;    /* undefined for offset 1, but safe return */

    /* Grow cache as needed */
    while (cache_len < (size_t)n) {
        seq_t k = next_scan;
        while (true) {
            /* test current candidate k */
            if (has_64(k) && !has_64(k - 1)) {
                /* store result */
                if (cache_len >= cache_cap) {
                    size_t new_cap = (cache_cap == 0) ? 16 : cache_cap * 2;
                    seq_t *new_cache = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
                    if (!new_cache) {
                        /* allocation failure – abort */
                        exit(1);
                    }
                    cache = new_cache;
                    cache_cap = new_cap;
                }
                cache[cache_len++] = k;
                next_scan = k + 1;          /* start next search after this k */
                break;
            }
            ++k;   /* continue scanning */
        }
    }
    return cache[n - 1];
}
